referenceSolutions.javascript:
export function solve(initial, operations) {
  const attributes = { ...initial },
    changes = [];
  for (const op of operations) {
    if (op.kind === "set") {
      for (const k of Object.keys(op.values)) {
        if (!Object.hasOwn(attributes, k) || attributes[k] !== op.values[k]) {
          changes.push({
            key: k,
            previous: Object.hasOwn(attributes, k) ? attributes[k] : null,
            value: op.values[k],
          });
          attributes[k] = op.values[k];
        }
      }
    } else if (Object.hasOwn(attributes, op.key)) {
      changes.push({ key: op.key, previous: attributes[op.key], value: null });
      delete attributes[op.key];
    }
  }
  return { attributes, changes };
}

